using System;using System.IO;using System.Linq;using System.Reflection;using NUnit.Framework;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public sealed class CampingSolidPineGuardTests
{
    static Type Author=>Type.GetType("LWS.TruckCamping.Editor.CampingSolidPineAuthoring, Assembly-CSharp-Editor",true);
    static object Invoke(string name,params object[] args)=>Author.GetMethod(name).Invoke(null,args);
    static string Constant(string name)=>(string)Author.GetField(name).GetRawConstantValue();
    [Test]public void DetachedTreeRecordMutationRefusesWithoutChangingActualTerrainOrPrototype()
    {
        const string path="Assets/TruckCamping/Models/Camp Haul Vista terrain 0 0.asset";var data=AssetDatabase.LoadAssetAtPath<TerrainData>(path);string before=(string)Invoke("Digest",path);var clone=UnityEngine.Object.Instantiate(data);
        try{clone.name=data.name;var expected=clone.treePrototypes[0].prefab;Invoke("ValidatePreservedTile",clone,0,expected);var trees=clone.treeInstances;trees[0].widthScale+=.01f;clone.SetTreeInstances(trees,false);var error=Assert.Throws<TargetInvocationException>(()=>Invoke("ValidatePreservedTile",clone,0,expected));Assert.That(error.InnerException,Is.TypeOf<InvalidOperationException>());Assert.That((string)Invoke("Digest",path),Is.EqualTo(before));}
        finally{UnityEngine.Object.DestroyImmediate(clone);}
    }
    [Test]public void DetachedUnknownPrototypeOrBendRefusesWithoutSavingAnyTerrain()
    {
        const string path="Assets/TruckCamping/Models/Camp Haul Vista terrain 0 0.asset";var data=AssetDatabase.LoadAssetAtPath<TerrainData>(path);string before=(string)Invoke("Digest",path);var clone=UnityEngine.Object.Instantiate(data);
        try{clone.name=data.name;var expected=clone.treePrototypes[0].prefab;clone.treePrototypes=new[]{new TreePrototype{prefab=expected,bendFactor=.3f}};Assert.That(Assert.Throws<TargetInvocationException>(()=>Invoke("ValidatePreservedTile",clone,0,expected)).InnerException,Is.TypeOf<InvalidOperationException>());clone.treePrototypes=new[]{new TreePrototype{prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Constant("SourcePrefab")),bendFactor=.2f}};Assert.That(Assert.Throws<TargetInvocationException>(()=>Invoke("ValidatePreservedTile",clone,0,expected)).InnerException,Is.TypeOf<InvalidOperationException>());Assert.That((string)Invoke("Digest",path),Is.EqualTo(before));}
        finally{UnityEngine.Object.DestroyImmediate(clone);}
    }
    [Test]public void ExistingOwnedOutputAndOrphanMetaRefuseWithoutChangingTheirBytes()
    {
        string dir=Path.GetFullPath("Logs/TruckSports/Impossible07/SolidPineRefusal/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string path=Path.Combine(dir,"custom.prefab");
        try{File.WriteAllText(path,"EXACT_CUSTOM_OUTPUT_PRESERVE");string before=(string)Invoke("Digest",path);Assert.That(Assert.Throws<TargetInvocationException>(()=>Invoke("RequireAbsentOutput",path)).InnerException,Is.TypeOf<InvalidOperationException>());Assert.That((string)Invoke("Digest",path),Is.EqualTo(before));File.Delete(path);File.WriteAllText(path+".meta","EXACT_ORPHAN_META_PRESERVE");before=(string)Invoke("Digest",path+".meta");Assert.That(Assert.Throws<TargetInvocationException>(()=>Invoke("RequireAbsentOutput",path)).InnerException,Is.TypeOf<InvalidOperationException>());Assert.That((string)Invoke("Digest",path+".meta"),Is.EqualTo(before));}
        finally{if(File.Exists(path))File.Delete(path);if(File.Exists(path+".meta"))File.Delete(path+".meta");Directory.Delete(dir);}
    }
    [Test]public void ActualConnectedJc07FitRetainsMeshesMaterialsAndTwoLodsWithZeroEnabledColliders()
    {
        string path=Constant("SourcePrefab"),before=(string)Invoke("Digest",path);var source=AssetDatabase.LoadAssetAtPath<GameObject>(path);var preview=EditorSceneManager.NewPreviewScene();
        try{var model=(GameObject)PrefabUtility.InstantiatePrefab(source,preview);var former=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Constant("FormerPrefab")),preview);var meshes=model.GetComponentsInChildren<MeshFilter>(true).Select(f=>f.sharedMesh).ToArray();var mats=model.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).ToArray();Assert.That(model.GetComponentsInChildren<Collider>(true).Count(c=>c.enabled),Is.EqualTo(2));Invoke("ConfigureOwnedInstance",model,former);Assert.That(model.transform.localScale,Is.EqualTo(Vector3.one));Assert.That(model.transform.localPosition,Is.EqualTo(Vector3.zero));Assert.That(model.transform.localRotation,Is.EqualTo(Quaternion.identity));CollectionAssert.AreEqual(meshes,model.GetComponentsInChildren<MeshFilter>(true).Select(f=>f.sharedMesh));CollectionAssert.AreEqual(mats,model.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials));Assert.That(model.GetComponentsInChildren<Collider>(true).Length,Is.EqualTo(2));Assert.That(model.GetComponentsInChildren<Collider>(true).All(c=>!c.enabled),Is.True);Assert.That(model.GetComponentsInChildren<Rigidbody>(true),Is.Empty);CollectionAssert.AreEqual(new[]{.25f,.01f},model.GetComponent<LODGroup>().GetLODs().Select(l=>l.screenRelativeTransitionHeight));var bounds=(Bounds)Invoke("RenderBounds",model);var old=(Bounds)Invoke("RenderBounds",former);Assert.That(bounds.size.y,Is.EqualTo(old.size.y).Within(.001f));Assert.That(bounds.size.x,Is.LessThanOrEqualTo(old.size.x+.001f));Assert.That(bounds.size.z,Is.LessThanOrEqualTo(old.size.z+.001f));Assert.That((string)Invoke("Digest",path),Is.EqualTo(before));}
        finally{EditorSceneManager.ClosePreviewScene(preview);}
    }
}
public sealed class CampingSolidPineAppliedTests
{
    static Type Author=>Type.GetType("LWS.TruckCamping.Editor.CampingSolidPineAuthoring, Assembly-CSharp-Editor",true);
    static string Digest(string path)=>(string)Author.GetMethod("Digest").Invoke(null,new object[]{path});
    static string Semantic(TerrainData data)=>(string)Author.GetMethod("Semantic").Invoke(null,new object[]{data});
    [Serializable]sealed class Row{public string path,guid,beforeSha256,afterSha256,metaSha256,preservedDigest;public int trees;}
    [Serializable]sealed class Input{public string path,sha256;}
    [Serializable]sealed class Receipt{public string status,backup,source,previousOwned,owned,worldBefore,worldAfter;public int disabledColliders;public Row[] files;public Input[] retainedInputs;}
    static Receipt Read()=>JsonUtility.FromJson<Receipt>(File.ReadAllText((string)Author.GetField("LatestReceipt").GetRawConstantValue()));
    [Test]public void FourActualTilesRetainEveryOriginalPayloadGuidAndExactSavedStageBackups()
    {
        var r=Read();Assert.That(r.status,Does.StartWith("ONLY_FOUR_TREE_PROTOTYPE_REFS_CHANGED"));Assert.That(r.files.Length,Is.EqualTo(4));Assert.That(r.files.Sum(f=>f.trees),Is.EqualTo(2297));string folder="SolidPineValidation"+Guid.NewGuid().ToString("N"),temp="Assets/TruckCamping/Tests/"+folder;AssetDatabase.CreateFolder("Assets/TruckCamping/Tests",folder);
        try{for(int i=0;i<4;i++){var row=r.files[i];string backup=Path.Combine(r.backup,i+"-vista.asset");Assert.That(Digest(backup),Is.EqualTo(row.beforeSha256));Assert.That(Digest(backup+".meta"),Is.EqualTo(row.metaSha256));string path=temp+"/prior"+i+".asset";File.Copy(backup,path);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var prior=AssetDatabase.LoadAssetAtPath<TerrainData>(path);var current=AssetDatabase.LoadAssetAtPath<TerrainData>(row.path);Assert.That(Semantic(prior),Is.EqualTo(row.preservedDigest));Assert.That(Semantic(current),Is.EqualTo(row.preservedDigest));CollectionAssert.AreEqual(prior.treeInstances,current.treeInstances);Assert.That(AssetDatabase.GetAssetPath(prior.treePrototypes[0].prefab),Is.EqualTo(r.previousOwned));Assert.That(AssetDatabase.GetAssetPath(current.treePrototypes[0].prefab),Is.EqualTo(r.owned));Assert.That(current.treePrototypes[0].bendFactor,Is.EqualTo(.2f));Assert.That(Digest(row.path),Is.EqualTo(row.afterSha256));Assert.That(Digest(row.path+".meta"),Is.EqualTo(row.metaSha256));Assert.That(AssetDatabase.AssetPathToGUID(row.path),Is.EqualTo(row.guid));}}
        finally{AssetDatabase.DeleteAsset(temp);}
        foreach(var input in r.retainedInputs.Where(x=>!x.path.Contains("Camp Haul shared wilderness.prefab")))Assert.That(Digest(input.path),Is.EqualTo(input.sha256),"Original scenes/nav/vendor/oldVista assets remain exact.");
        Assert.That(Digest(Path.Combine(r.backup,"world-before.prefab")),Is.EqualTo(r.worldBefore));Assert.That(Digest(Path.Combine(r.backup,"world-after.prefab")),Is.EqualTo(r.worldAfter));Assert.That(r.worldBefore,Is.EqualTo(r.worldAfter));const string shared="Assets/TruckCamping/Prefabs/Camp Haul shared wilderness.prefab";
        if(Digest(shared)!=r.worldAfter){var water=Type.GetType("LWS.TruckCamping.Editor.CampingWaterPresentationAuthoring, Assembly-CSharp-Editor",false);Assert.That(water,Is.Not.Null,"Only the explicitly authorized strict water reference transition may follow this retained tree stage.");var verify=water.GetMethod("VerifyWaterDescendsFrom",BindingFlags.Public|BindingFlags.Static);Assert.That(verify,Is.Not.Null);TestContext.WriteLine("EXPLICIT_TREE_TO_WATER_CHAIN "+verify.Invoke(null,new object[]{r.worldAfter}));}
        else Assert.That(Digest(shared),Is.EqualTo(r.worldAfter));
    }
    [Test]public void SavedOwnedJc07IsTrueUnitVariantWithOriginalVendorLodsAndNoActivePhysics()
    {
        var r=Read();var owned=AssetDatabase.LoadAssetAtPath<GameObject>(r.owned);var source=AssetDatabase.LoadAssetAtPath<GameObject>(r.source);Assert.That(owned,Is.Not.Null);Assert.That(PrefabUtility.GetPrefabAssetType(owned),Is.EqualTo(PrefabAssetType.Variant));Assert.That(PrefabUtility.GetCorrespondingObjectFromOriginalSource(owned),Is.SameAs(source));Assert.That(owned.transform.localScale,Is.EqualTo(Vector3.one));Assert.That(owned.transform.localPosition,Is.EqualTo(Vector3.zero));Assert.That(owned.transform.localRotation,Is.EqualTo(Quaternion.identity));CollectionAssert.AreEqual(source.GetComponentsInChildren<MeshFilter>(true).Select(f=>f.sharedMesh),owned.GetComponentsInChildren<MeshFilter>(true).Select(f=>f.sharedMesh));CollectionAssert.AreEqual(source.GetComponentsInChildren<Renderer>(true).SelectMany(x=>x.sharedMaterials),owned.GetComponentsInChildren<Renderer>(true).SelectMany(x=>x.sharedMaterials));Assert.That(owned.GetComponentsInChildren<Collider>(true).Length,Is.EqualTo(2));Assert.That(owned.GetComponentsInChildren<Collider>(true).All(c=>!c.enabled),Is.True);Assert.That(owned.GetComponentsInChildren<Rigidbody>(true),Is.Empty);CollectionAssert.AreEqual(new[]{.25f,.01f},owned.GetComponent<LODGroup>().GetLODs().Select(l=>l.screenRelativeTransitionHeight));Assert.That(r.disabledColliders,Is.EqualTo(2));
        var preview=EditorSceneManager.NewPreviewScene();try{var a=(GameObject)PrefabUtility.InstantiatePrefab(owned,preview);var b=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(r.previousOwned),preview);var bounds=(Bounds)Author.GetMethod("RenderBounds").Invoke(null,new object[]{a});var former=(Bounds)Author.GetMethod("RenderBounds").Invoke(null,new object[]{b});Assert.That(bounds.size.y,Is.EqualTo(former.size.y).Within(.001f));Assert.That(bounds.size.y,Is.EqualTo(16.6f).Within(.002f));Assert.That(bounds.min.y,Is.EqualTo(former.min.y).Within(.001f));Assert.That(bounds.size.x,Is.LessThanOrEqualTo(former.size.x+.001f));Assert.That(bounds.size.z,Is.LessThanOrEqualTo(former.size.z+.001f));}finally{EditorSceneManager.ClosePreviewScene(preview);}
    }
    [Test]public void RepeatedUpgradeRefusesExistingOwnedOutputWithoutChangingCurrentDataOrWorld()
    {
        var r=Read();var paths=r.files.SelectMany(f=>new[]{f.path,f.path+".meta"}).Concat(new[]{r.owned,r.owned+".meta",r.previousOwned,r.previousOwned+".meta","Assets/TruckCamping/Prefabs/Camp Haul shared wilderness.prefab"}).ToArray();var hashes=paths.Select(Digest).ToArray();var error=Assert.Throws<TargetInvocationException>(()=>Author.GetMethod("UpgradeExactReviewedVistaPrototypesToJc07").Invoke(null,null));Assert.That(error.InnerException,Is.TypeOf<InvalidOperationException>());CollectionAssert.AreEqual(hashes,paths.Select(Digest));
    }
}
